analyze.mjs.text:
// Classifies a bucket's raw listing + ACL responses (real HTTP responses,
// collected by probe.mjs's live requests) into a verdict about whether an
// S3 bucket is publicly exposed, and how.
//
// Pure function, no I/O, no network -- imported identically by the CLI
// (check.mjs) and the browser page (index.html).
//
// What this tool reads and does not read: S3's listing and ACL documents
// are XML describing the BUCKET (which keys exist, which grantees have
// which permission) -- never the bytes of a stored object. `extractKeys`
// below returns object KEY NAMES ONLY, capped to the first 10 the bucket's
// own response already capped itself to (`?max-keys=10`) -- never an
// object's content, size beyond what S3 reports, or any fetched file. A
// bucket that lists its own contents to an anonymous request is already
// evidence enough of the misconfiguration without this tool reading a
// single byte of what any of those files actually contain.
//
// Findings this tool names:
//
//   public-list             An unsigned GET to the bucket's own listing
//                            endpoint returned a real `ListBucketResult` --
//                            anyone who knows or guesses the bucket name can
//                            enumerate its object keys with no credentials.
//   public-write-acl        The bucket's ACL grants WRITE, WRITE_ACP, or
//                            FULL_CONTROL to the `AllUsers` group -- the
//                            most severe finding: anyone can upload,
//                            overwrite, or delete objects in this bucket.
//   public-read-acl         The bucket's ACL grants READ, READ_ACP, or
//                            FULL_CONTROL to the `AllUsers` group.
//   authenticated-users-grant  The ACL grants any permission to the
//                            `AuthenticatedUsers` group -- a commonly
//                            misunderstood setting: it does not mean "my
//                            own users", it means any AWS account holder
//                            anywhere, signed in with any AWS credentials
//                            at all.
//   blocked                 Both requests returned a clean AccessDenied
//                            (403) -- a healthy outcome; this tool cannot
//                            tell "correctly private" apart from "denied for
//                            some other reason", only that anonymous access
//                            was refused.
//   not-found                The bucket name does not exist
//                            (`NoSuchBucket`) -- most likely a typo; a
//                            negative result, not evidence either way about
//                            a real bucket.
//   error                    A request failed without a clean HTTP status
//                            (network error, timeout, a browser's
//                            CORS-blocked "failed to fetch"). Never read as
//                            either exposed or safe.

// S3's fixed well-known group URIs. Only these two are ever meaningful to a
// security check -- LogDelivery and others exist but grant nothing an
// anonymous internet visitor benefits from.
const ALL_USERS_URI = 'http://acs.amazonaws.com/groups/global/AllUsers';
const AUTHENTICATED_USERS_URI = 'http://acs.amazonaws.com/groups/global/AuthenticatedUsers';

const WRITE_PERMISSIONS = new Set(['WRITE', 'WRITE_ACP', 'FULL_CONTROL']);
const READ_PERMISSIONS = new Set(['READ', 'READ_ACP', 'FULL_CONTROL']);

function tag(xml, name) {
  const m = new RegExp(`<${name}>([^<]*)</${name}>`).exec(xml);
  return m ? m[1] : null;
}

function allTags(xml, name) {
  const re = new RegExp(`<${name}>([^<]*)</${name}>`, 'g');
  const out = [];
  let m;
  while ((m = re.exec(xml)) !== null) out.push(m[1]);
  return out;
}

/** Object key NAMES only, in the order S3's own response lists them --
 * already capped by this tool's own `?max-keys=10` request, so there is
 * nothing further to truncate here. See this file's header comment for why
 * object CONTENT is never read at all. */
export function extractKeys(xml) {
  if (typeof xml !== 'string') return [];
  return allTags(xml, 'Key');
}

/** Parses an `AccessControlPolicy` document into per-grantee-group
 * permission sets. Only the two group URIs a security finding can be built
 * from are extracted; canonical-user (individual AWS account) grants are
 * ignored -- they are not an anonymous-internet exposure. */
export function extractGroupGrants(xml) {
  if (typeof xml !== 'string') return { allUsers: [], authenticatedUsers: [] };
  const allUsers = new Set();
  const authenticatedUsers = new Set();
  const grantRe = /<Grant>([\s\S]*?)<\/Grant>/g;
  let m;
  while ((m = grantRe.exec(xml)) !== null) {
    const block = m[1];
    const uri = tag(block, 'URI');
    const permission = tag(block, 'Permission');
    if (!uri || !permission) continue;
    if (uri === ALL_USERS_URI) allUsers.add(permission);
    else if (uri === AUTHENTICATED_USERS_URI) authenticatedUsers.add(permission);
  }
  return { allUsers: [...allUsers], authenticatedUsers: [...authenticatedUsers] };
}

function classifyListing(listing) {
  if (!listing) return { state: 'error', error: 'no listing result' };
  if (!listing.ok) {
    const code = listing.text ? tag(listing.text, 'Code') : null;
    if (code === 'NoSuchBucket' || listing.status === 404 && !listing.text) {
      return { state: 'not-found' };
    }
    if (listing.status === 403 || code === 'AccessDenied') {
      return { state: 'blocked' };
    }
    return { state: 'error', error: listing.error ?? `HTTP ${listing.status ?? 'unknown'}` };
  }
  if (!/<ListBucketResult/.test(listing.text ?? '')) {
    // A 200 that is not a real listing document -- do not guess.
    return { state: 'error', error: 'unexpected response shape' };
  }
  const keys = extractKeys(listing.text);
  return { state: 'public-list', keys, keyCount: keys.length };
}

function classifyAcl(acl) {
  if (!acl) return { state: 'error', error: 'no ACL result' };
  if (!acl.ok) {
    const code = acl.text ? tag(acl.text, 'Code') : null;
    if (code === 'NoSuchBucket') return { state: 'not-found' };
    if (acl.status === 403 || code === 'AccessDenied') return { state: 'blocked' };
    return { state: 'error', error: acl.error ?? `HTTP ${acl.status ?? 'unknown'}` };
  }
  if (!/<AccessControlPolicy/.test(acl.text ?? '')) {
    return { state: 'error', error: 'unexpected response shape' };
  }
  const grants = extractGroupGrants(acl.text);
  return { state: 'readable', ...grants };
}

/**
 * @param {string} bucket - the bucket name checked, for display only
 * @param {{listing: object, acl: object}} raw - probe.mjs's raw per-request results
 */
export function buildReport(bucket, raw) {
  const listing = classifyListing(raw?.listing);
  const acl = classifyAcl(raw?.acl);
  const findings = [];

  if (listing.state === 'public-list') {
    findings.push({
      id: 'public-list',
      severity: 'critical',
      title: 'Anonymous listing is enabled -- anyone can enumerate this bucket\'s object keys',
      detail:
        `An unsigned GET request listed ${listing.keyCount} object key(s) with no credentials at all. ` +
        `Object CONTENTS are never fetched by this report -- only the key (file) names S3's own listing ` +
        `response already returned.`,
      sampleKeys: listing.keys,
    });
  }

  if (acl.state === 'readable') {
    const write = acl.allUsers.filter((p) => WRITE_PERMISSIONS.has(p));
    const read = acl.allUsers.filter((p) => READ_PERMISSIONS.has(p));
    if (write.length > 0) {
      findings.push({
        id: 'public-write-acl',
        severity: 'critical',
        title: 'The bucket ACL grants write access to anyone on the internet',
        detail:
          `The "AllUsers" group (anonymous, no AWS account required) holds ${write.join(', ')} on this ` +
          `bucket's ACL -- anyone can upload, overwrite, or delete objects, not just read them.`,
        permissions: write,
      });
    }
    if (read.length > 0) {
      findings.push({
        id: 'public-read-acl',
        severity: 'critical',
        title: 'The bucket ACL grants read access to anyone on the internet',
        detail:
          `The "AllUsers" group (anonymous, no AWS account required) holds ${read.join(', ')} on this ` +
          `bucket's ACL.`,
        permissions: read,
      });
    }
    if (acl.authenticatedUsers.length > 0) {
      findings.push({
        id: 'authenticated-users-grant',
        severity: 'danger',
        title: '"AuthenticatedUsers" holds a grant -- this means ANY AWS account, not your own users',
        detail:
          `The ACL grants ${acl.authenticatedUsers.join(', ')} to the "AuthenticatedUsers" group. This is ` +
          `a commonly misunderstood S3 setting: it does not scope to your organisation's users -- it means ` +
          `anyone who has ever created any AWS account, signed in with their own credentials.`,
        permissions: acl.authenticatedUsers,
      });
    }
  }

  const notFound = listing.state === 'not-found' || acl.state === 'not-found';
  const errors = [listing, acl].filter((c) => c.state === 'error');
  const blocked = [listing, acl].filter((c) => c.state === 'blocked');

  return {
    bucket,
    listing,
    acl,
    findings,
    criticalCount: findings.filter((f) => f.severity === 'critical').length,
    dangerCount: findings.filter((f) => f.severity === 'danger').length,
    notFound,
    blockedCount: blocked.length,
    errors: errors.map((e) => e.error),
    incomplete: errors.length > 0,
    ok: findings.length === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends two unsigned GET requests to a named S3 bucket's own REST
// endpoint -- one asking it to list its contents, one asking to read its
// ACL -- and reports whether anonymous listing is enabled and whether the
// ACL grants read/write to "AllUsers" or "AuthenticatedUsers". Object
// CONTENTS are never fetched, only key (file) names and ACL grant metadata.
// Your machine, real requests -- no request goes through this portfolio.
//
//   node check.mjs <bucket-name> [--json] [--timeout <ms>]
//
// Only run this against a bucket you own or are authorised to test -- treat
// it the same as you would `curl` or the AWS CLI aimed at someone else's
// bucket. This never sends anything but GET requests and never
// writes/modifies anything on the target.
//
// Exit code 0 when no exposure is found (including "bucket does not
// exist"); 1 when at least one finding is confirmed.

import { checkBucket } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Bucket: ${report.bucket}`);

  if (report.notFound) {
    lines.push('This bucket name does not exist (NoSuchBucket) -- check for a typo.');
    return lines.join('\n');
  }

  if (report.findings.length === 0) {
    lines.push('No exposure found: anonymous listing is blocked and no public ACL grant was found.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      if (f.sampleKeys?.length) lines.push(`     keys: ${f.sampleKeys.join(', ')}`);
      lines.push('');
    }
  }

  if (report.blockedCount > 0) {
    lines.push(`${report.blockedCount} request(s) cleanly blocked (AccessDenied) -- a healthy outcome.`);
  }
  if (report.errors.length > 0) {
    lines.push(`${report.errors.length} request(s) could not be classified: ${report.errors.join('; ')}`);
  }

  lines.push('');
  lines.push(
    'This is evidence from two unsigned requests, not a full security audit -- see README.md for ' +
      'what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  let bucket = null;
  let json = false;
  let timeoutMs;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') json = true;
    else if (argv[i] === '--timeout') timeoutMs = Number(argv[++i]);
    else if (!argv[i].startsWith('--') && bucket === null) bucket = argv[i];
  }
  return { bucket, json, timeoutMs };
}

/** Pure orchestration: given a checkBucket function (real network, or a
 * stub in tests), fetch and classify. Kept separate from main() so tests
 * can inject a fake `checkBucketFn` instead of hitting the network. */
export async function runCheck(bucket, { checkBucketFn = checkBucket, timeoutMs } = {}) {
  const raw = await checkBucketFn(bucket, timeoutMs ? { timeoutMs } : undefined);
  return buildReport(bucket, raw);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.bucket) {
    console.error('Usage: node check.mjs <bucket-name> [--json] [--timeout <ms>]');
    console.error('Only run this against a bucket you own or are authorised to test.');
    process.exit(2);
  }

  let report;
  try {
    report = await runCheck(args.bucket, { timeoutMs: args.timeoutMs });
  } catch (err) {
    console.error(err.message ?? String(err));
    process.exit(2);
  }

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Real-network layer: given an S3 bucket name, sends two plain, unsigned GET
// requests -- one asking the bucket to list its own contents
// (`?max-keys=10`), one asking to read its ACL (`?acl`) -- and returns
// exactly what came back: status, response headers, and a byte-capped body.
// Nothing here classifies a result; that is analyze.mjs's job. Deliberately
// the same module imported unmodified by the CLI (Node 22's built-in
// `fetch`) and by the browser page (`index.html` imports it directly), the
// same shape `ventures/dotenv-exposure-check/probe.mjs` and
// `ventures/git-exposure-check/probe.mjs` document.
//
// Both requests are unsigned (no AWS credentials involved anywhere in this
// tool) -- exactly the request an anonymous visitor, or `curl`, already
// makes. S3's anonymous-access model is what this tool reads: a bucket
// either answers an unsigned GET or it returns AccessDenied, and that
// decision is made entirely by the bucket's own ACL and bucket-policy
// configuration, not by anything this tool sends.
//
// This module never fetches an actual object's content -- only the bucket's
// own listing and ACL documents, both of which S3 returns as XML describing
// the bucket itself, never a stored file's bytes. See analyze.mjs for what
// is and is not extracted from those two documents.
//
// This module only ever talks to the one bucket name the caller supplies, at
// the fixed S3 REST endpoints below. It never attempts a PUT, POST, or
// DELETE.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  's3-bucket-exposure-check/1 (+https://duncan-haywood.github.io/monorepo-projects/s3-bucket-exposure-check/)';
// A bucket listing or ACL document is normally a few KB of XML. This cap is
// generous enough to still classify a real response while bounding what this
// tool ever holds in memory.
const MAX_BODY_BYTES = 2_000_000;

// A bucket name must be DNS-compatible for virtual-hosted-style addressing
// (lowercase letters, digits, dots, hyphens, 3-63 chars) -- reject anything
// else before it is ever used to build a URL, rather than let a malformed
// name produce a confusing fetch error.
const BUCKET_NAME_RE = /^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/;

export function isValidBucketName(name) {
  return typeof name === 'string' && BUCKET_NAME_RE.test(name);
}

/** Builds the virtual-hosted-style REST URL for a bucket, optionally pinned
 * to a specific region's endpoint once one has been discovered. */
export function bucketUrl(bucket, { region, query = '' } = {}) {
  const host = region ? `${bucket}.s3.${region}.amazonaws.com` : `${bucket}.s3.amazonaws.com`;
  return `https://${host}/${query}`;
}

async function timedFetch(url, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, {
      method: 'GET',
      headers: { 'user-agent': USER_AGENT, accept: 'application/xml,text/xml,*/*' },
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timer);
  }
}

async function readCapped(res, maxBytes) {
  if (!res.body?.getReader) {
    const text = await res.text();
    return text.length > maxBytes ? text.slice(0, maxBytes) : text;
  }
  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    chunks.push(value);
    if (total >= maxBytes) {
      try { await reader.cancel(); } catch { /* best effort */ }
      break;
    }
  }
  const combined = new Uint8Array(Math.min(total, maxBytes));
  let offset = 0;
  for (const chunk of chunks) {
    const room = combined.length - offset;
    if (room <= 0) break;
    combined.set(room < chunk.length ? chunk.subarray(0, room) : chunk, offset);
    offset += Math.min(chunk.length, room);
  }
  return new TextDecoder('utf-8', { fatal: false }).decode(combined);
}

/** One unsigned GET to a bucket's REST endpoint at the given query string
 * (`''` for a listing, `'?acl'` for the ACL document). Never throws on an
 * ordinary HTTP or network failure -- those come back as `ok: false` with
 * `error` set, the same discrimination every sibling checker's probe makes,
 * so a caller can tell "confirmed AccessDenied" (a clean status) apart from
 * "could not confirm either way" (a network error). */
export async function fetchBucketPath(bucket, query, { region, timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const url = bucketUrl(bucket, { region, query });
  let res;
  try {
    res = await timedFetch(url, timeoutMs, fetchImpl);
  } catch (err) {
    return { url, region: region ?? null, ok: false, status: null, text: null, error: err.message ?? String(err), regionHint: null };
  }
  const regionHint = res.headers?.get?.('x-amz-bucket-region') ?? null;
  let text = null;
  try {
    text = await readCapped(res, MAX_BODY_BYTES);
  } catch (err) {
    return { url, region: region ?? null, ok: false, status: res.status, text: null, error: err.message ?? String(err), regionHint };
  }
  return { url, region: region ?? null, ok: res.ok, status: res.status, text, error: res.ok ? null : `HTTP ${res.status}`, regionHint };
}

/** Fetches one bucket path, retrying once against the bucket's own region
 * endpoint if the first (global, us-east-1-style) request comes back with a
 * region mismatch -- S3 reports the correct region in the
 * `x-amz-bucket-region` header on both success and most error responses.
 * This is the same global-endpoint-then-regional-retry approach the
 * well-known open-source `S3Scanner` CLI uses, because unsigned requests to
 * a bucket outside `us-east-1` are frequently redirected. */
export async function fetchBucketPathWithRegionRetry(bucket, query, opts = {}) {
  const first = await fetchBucketPath(bucket, query, opts);
  const needsRetry = first.status === 301 || first.status === 400 || (first.regionHint && !opts.region);
  if (!needsRetry || !first.regionHint || first.regionHint === opts.region) return first;
  return fetchBucketPath(bucket, query, { ...opts, region: first.regionHint });
}

/** Full run for one bucket name: fetch the listing and the ACL document.
 * The listing runs first so its discovered region (if any) is reused for
 * the ACL request -- both live in the same region, so there is no reason to
 * pay for two independent region-discovery round trips. */
export async function checkBucket(bucket, { timeoutMs, fetchImpl } = {}) {
  if (!bucket) throw new Error('a bucket name is required');
  if (!isValidBucketName(bucket)) {
    throw new Error(`"${bucket}" is not a syntactically valid S3 bucket name`);
  }
  const listing = await fetchBucketPathWithRegionRetry(bucket, '?max-keys=10', { timeoutMs, fetchImpl });
  const region = listing.region ?? listing.regionHint ?? undefined;
  const acl = await fetchBucketPathWithRegionRetry(bucket, '?acl', { region, timeoutMs, fetchImpl });
  return { bucket, listing, acl };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// bucket name checked or anything about the result -- that is exactly the
// kind of thing that must not be transmitted anywhere, and this tool never
// reads it off the visitor's machine either.

const STORAGE_KEY = 's3-bucket-exposure-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters: opting out
// *removes* the counters, so a flag stored inside them would be deleted by
// the very act it records. `recordUsage` above consults it directly as well
// as taking the caller's argument.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem that
  // throws on a full quota skips the delete entirely, and the visitor gets
  // neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
